def parallel_waves(num_courses: int, adj: list[list[int]], in_degree: list[int]) -> list[list[int]]:
    queue = deque(i for i in range(num_courses) if in_degree[i] == 0)
    waves: list[list[int]] = []
    while queue:
        wave_size = len(queue)
        wave: list[int] = []
        for _ in range(wave_size):
            u = queue.popleft()
            wave.append(u)
            for v in adj[u]:
                in_degree[v] -= 1
                if in_degree[v] == 0:
                    queue.append(v)
        waves.append(wave)
    return waves

def min_completion_time(num_courses: int, durations: list[int], adj: list[list[int]], in_degree: list[int]) -> int:
    dp = durations[:]
    queue = deque(i for i in range(num_courses) if in_degree[i] == 0)
    visited = 0
    while queue:
        u = queue.popleft()
        visited += 1
        for v in adj[u]:
            if dp[u] + durations[v] > dp[v]:
                dp[v] = dp[u] + durations[v]
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)
    return max(dp, default=0) if visited == num_courses else -1
